  user_id INT NOT NULL,
  kind TEXT NOT NULL
);
INSERT INTO events (user_id, kind)
SELECT (g % 5000) + 1, (ARRAY['click','view','purchase'])[1 + (g % 3)]
FROM generate_series(1, 30000) g;
ANALYZE events;
CREATE OR REPLACE FUNCTION scan_kind(q text) RETURNS text AS $$
DECLARE p jsonb; s text;
BEGIN
  EXECUTE 'EXPLAIN (FORMAT JSON) ' || q INTO p;
  s := p::text;
  IF s LIKE '%Index Only Scan%' THEN RETURN 'index-only';
  ELSIF s LIKE '%Index Scan%' OR s LIKE '%Bitmap%' THEN RETURN 'index';
  ELSE RETURN 'seq'; END IF;
END $$ LANGUAGE plpgsql;

CREATE TABLE visits (id SERIAL PRIMARY KEY, city TEXT NOT NULL);
INSERT INTO visits (city)
SELECT CASE WHEN g % 100 = 0 THEN 'lima' ELSE 'bogota' END
FROM generate_series(1, 20000) g;
CREATE OR REPLACE FUNCTION est_quality(q text) RETURNS text AS $$
DECLARE p jsonb; est numeric; act numeric;
BEGIN
  EXECUTE 'EXPLAIN (ANALYZE, FORMAT JSON) ' || q INTO p;
  est := (p->0->'Plan'->>'Plan Rows')::numeric;
  act := (p->0->'Plan'->>'Actual Rows')::numeric;
  IF act = 0 THEN RETURN 'empty'; END IF;
  IF est BETWEEN act * 0.5 AND act * 2 THEN RETURN 'accurate'; ELSE RETURN 'off'; END IF;
END $$ LANGUAGE plpgsql;

data.verification_query:
SELECT est_quality('SELECT * FROM visits WHERE city = ''lima''') AS estimate,
       (SELECT count(*)::int FROM pg_stats
        WHERE tablename = 'visits' AND attname = 'city') AS stats_rows;

